        "cpp" => "cpp",
        "c" => "c",
        "bash" => "bash",
        "sh" => "__invalid__",
        _ => lower.as_str(),
    };
    if mapped == "__invalid__" { return None; }
    for info in lang_table() {
        if info.canonical.to_ascii_lowercase() == mapped {
            return Some(info);
        }
    }
    None
}

fn lang_for_file(path: &Path) -> Option<LangInfo> {
