// ===== Pattern parsing =====
#[derive(Debug, Clone)]
enum PatPart {
    Lit(String),
    Single(String), // name, "$___" for anon? we treat anon as Single with special name
    Multi(Option<String>), // None = anonymous $$$
}

fn is_var_start(c: char) -> bool {
    c == '_' || c.is_ascii_uppercase()
}
fn is_var_char(c: char) -> bool {
    c == '_' || c.is_ascii_uppercase() || c.is_ascii_digit()
}

fn parse_pat_parts(pat: &str) -> Vec<PatPart> {
    let mut parts = Vec::new();
    let mut lit = String::new();
    let chars: Vec<char> = pat.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        if chars[i] == '$' {
            // check $$$
            if i + 2 < chars.len() && chars[i+1] == '$' && chars[i+2] == '$' {
                // $$$...
                let mut j = i + 3;
                if j < chars.len() && is_var_start(chars[j]) {
                    let start = j;
                    j += 1;
                    while j < chars.len() && is_var_char(chars[j]) { j += 1; }
                    let name: String = chars[start..j].iter().collect();
                    if !lit.is_empty() { parts.push(PatPart::Lit(lit.clone())); lit.clear(); }
                    parts.push(PatPart::Multi(Some(name)));
                    i = j;
                    continue;
                } else {
                    // $$$ anonymous
                    if !lit.is_empty() { parts.push(PatPart::Lit(lit.clone())); lit.clear(); }
                    parts.push(PatPart::Multi(None));
                    i += 3;
                    continue;
                }
            }
            // check $$ + name (single)
            if i + 1 < chars.len() && chars[i+1] == '$' {
                // $$A ?
                if i + 2 < chars.len() && is_var_start(chars[i+2]) {
                    let mut j = i + 2;
                    let start = j;
                    j += 1;
                    while j < chars.len() && is_var_char(chars[j]) { j += 1; }
                    let name: String = chars[start..j].iter().collect();
                    if !lit.is_empty() { parts.push(PatPart::Lit(lit.clone())); lit.clear(); }
                    parts.push(PatPart::Single(name));
                    i = j;
                    continue;
                } else {
                    // literal $$
                    lit.push('$');
                    lit.push('$');
                    i += 2;
                    continue;
                }
            }
            // check $ + name
            if i + 1 < chars.len() && is_var_start(chars[i+1]) {
                let mut j = i + 1;
                let start = j;
                j += 1;
                while j < chars.len() && is_var_char(chars[j]) { j += 1; }
                let name: String = chars[start..j].iter().collect();
                if !lit.is_empty() { parts.push(PatPart::Lit(lit.clone())); lit.clear(); }
                parts.push(PatPart::Single(name));
                i = j;
                continue;
            } else {
                lit.push('$');
                i += 1;
                continue;
            }
        } else {
            lit.push(chars[i]);
            i += 1;
        }
    }
    if !lit.is_empty() { parts.push(PatPart::Lit(lit)); }
    parts
}

fn escape_regex(s: &str) -> String {
    let mut out = String::new();
    for c in s.chars() {
        match c {
            'a'..='z' | 'A'..='Z' | '0'..='9' | '_' => out.push(c),
            _ => { out.push('\\'); out.push(c); }
        }
    }
    out
}

// Convert literal to regex fragment allowing flexible whitespace
fn lit_to_regex(lit: &str) -> String {
    // split on whitespace sequences, keep them
    // First, split lit into chunks separated by whitespace
    let mut result = String::new();
    // Use regex to split? manual
    let chars: Vec<char> = lit.chars().collect();
    let mut i = 0;
    let mut first_chunk = true;
    while i < chars.len() {
        // skip whitespace -> produce \s+
        if chars[i].is_whitespace() {
            while i < chars.len() && chars[i].is_whitespace() { i += 1; }
            result.push_str("\\s+");
            first_chunk = false;
            continue;
        }
        // collect non-whitespace chunk
        let start = i;
        while i < chars.len() && !chars[i].is_whitespace() { i += 1; }
        let chunk: String = chars[start..i].iter().collect();
        // within chunk, split into word/punct tokens and join with \s*
        // token regex: \w+ or single non-word char
        let mut tokens: Vec<String> = Vec::new();
        let cchars: Vec<char> = chunk.chars().collect();
