fn match_to_json(m: &MatchInfo, content: &str, file: &str, lang_display: &str, rewrite: Option<&str>) -> serde_json::Value {
    let (sl, sc) = byte_to_line_col(content, m.start);
    let (el, ec) = byte_to_line_col(content, m.end);
    let (_, _, lines_text, leading, trailing) = line_range_for_match(content, m.start, m.end);
    let mut single_map = serde_json::Map::new();
    for (k, v) in &m.single_vars {
        let (vs_l, vs_c) = byte_to_line_col(content, v.start);
        let (ve_l, ve_c) = byte_to_line_col(content, v.end);
        single_map.insert(k.clone(), serde_json::json!({
            "text": v.text,
            "range": {
                "byteOffset": {"start": v.start, "end": v.end},
                "start": {"line": vs_l, "column": vs_c},
                "end": {"line": ve_l, "column": ve_c}
            }
        }));
    }
    let mut multi_map = serde_json::Map::new();
    for (k, vec) in &m.multi_vars {
        let arr: Vec<serde_json::Value> = vec.iter().map(|v| {
            let (vs_l, vs_c) = byte_to_line_col(content, v.start);
            let (ve_l, ve_c) = byte_to_line_col(content, v.end);
            serde_json::json!({
                "text": v.text,
                "range": {
                    "byteOffset": {"start": v.start, "end": v.end},
                    "start": {"line": vs_l, "column": vs_c},
                    "end": {"line": ve_l, "column": ve_c}
                }
            })
        }).collect();
        multi_map.insert(k.clone(), serde_json::Value::Array(arr));
    }
    let mut obj = serde_json::Map::new();
    obj.insert("text".to_string(), serde_json::Value::String(m.text.clone()));
    obj.insert("range".to_string(), serde_json::json!({
        "byteOffset": {"start": m.start, "end": m.end},
        "start": {"line": sl, "column": sc},
