fn parse_yaml_rules(text: &str) -> Result<Vec<YamlRule>, String> {
    // split on --- (YAML multi-doc)
    let mut out = Vec::new();
    // serde_yaml can parse multiple docs? Use deserializer
    // Simple: split by lines "---"
    let docs: Vec<String> = {
        let mut docs = Vec::new();
        let mut cur = String::new();
        for line in text.lines() {
            if line.trim() == "---" {
                if !cur.trim().is_empty() { docs.push(cur.clone()); cur.clear(); }
            } else {
                cur.push_str(line); cur.push('\n');
            }
        }
        if !cur.trim().is_empty() { docs.push(cur); }
        docs
    };
    if docs.is_empty() {
        // try single doc
        docs.clone();
    }
    for doc in docs {
        if doc.trim().is_empty() { continue; }
