                    }
                }
                if first {
                    // all contained only nots? Then candidates should be all pattern matches? Actually `all: [not: ...]` alone? Unlikely. Return empty?
                    candidates = Vec::new();
                }
                // Apply not filters: remove candidates that match any not subrule at same range?
                for not_sub in not_rules {
                    if let Some(m) = not_sub.as_mapping() {
                        if let Some(not_inner) = m.get(&serde_yaml::Value::String("not".to_string())) {
                            let not_ms = find_subrule_matches(not_inner, content);
                            candidates.retain(|c| {
                                !not_ms.iter().any(|n| n.start==c.start && n.end==c.end)
                            });
                        }
                    }
                }
                candidates = filter_by_relations_vec(candidates, content, obj);
                return candidates;
            }
        }
        // not at top? `rule: {not: {pattern: ...}}` – what does it match? It matches all nodes that don't match subrule? Original for `not` alone? Unlikely tested. We'll return empty.
        if obj.contains_key(&serde_yaml::Value::String("not".to_string())) {
            return Vec::new();
        }
        // inside/has/precedes/follows at top without pattern/kind? e.g., `rule: {inside: ...}`? Unlikely. Return empty.
        // matches, constraints? Ignore.
    }
    Vec::new()
}

fn find_subrule_matches(sub: &serde_yaml::Value, content: &str) -> Vec<MatchInfo> {
    // sub is a rule object like {pattern: ...} or {kind: ...} or {any: ...} etc.
    // Create a fake YamlRule with this as rule_obj
    let fake = YamlRule { id: "".to_string(), language: None, severity: "".to_string(), message: "".to_string(), note: None, rule_obj: sub.clone(), fix: None };
    find_rule_matches(&fake, content, "")
}

fn filter_by_relations(matches: Vec<MatchInfo>, content: &str, obj: &serde_yaml::Mapping) -> Vec<MatchInfo> {
    filter_by_relations_vec(matches, content, obj)
}

fn filter_by_relations_vec(mut matches: Vec<MatchInfo>, content: &str, obj: &serde_yaml::Mapping) -> Vec<MatchInfo> {
    // Check for inside, has, precedes, follows
    if let Some(inside_val) = obj.get(&serde_yaml::Value::String("inside".to_string())) {
        // inside can be a rule object or {pattern: ..., range: ...}? Simplify: find sub-matches and keep candidates inside them
        let sub_ms = find_subrule_matches_inner(inside_val, content);
        matches.retain(|c| {
            sub_ms.iter().any(|s| s.start <= c.start && c.end <= s.end && !(s.start==c.start && s.end==c.end) )
            // Note: should be strictly inside? For function containing console.log, function's range contains log's range, not equal. Good.
        });
    }
    if let Some(has_val) = obj.get(&serde_yaml::Value::String("has".to_string())) {
        let sub_ms = find_subrule_matches_inner(has_val, content);
        matches.retain(|c| {
            sub_ms.iter().any(|s| c.start <= s.start && s.end <= c.end && !(s.start==c.start && s.end==c.end))
        });
    }
    if let Some(precedes_val) = obj.get(&serde_yaml::Value::String("precedes".to_string())) {
        let sub_ms = find_subrule_matches_inner(precedes_val, content);
        matches.retain(|c| {
            sub_ms.iter().any(|s| c.end <= s.start)
        });
    }
    if let Some(follows_val) = obj.get(&serde_yaml::Value::String("follows".to_string())) {
        let sub_ms = find_subrule_matches_inner(follows_val, content);
        matches.retain(|c| {
            sub_ms.iter().any(|s| s.end <= c.start)
        });
    }
    matches
}

fn find_subrule_matches_inner(val: &serde_yaml::Value, content: &str) -> Vec<MatchInfo> {
    // inside/has value can be {pattern: ...} or {any: ...} etc., or directly a rule object
    // It may also have `stopBy` etc., ignore.
    // If val is mapping with `pattern` etc., treat as rule
    find_subrule_matches(val, content)
}

