    match report_style.as_str() {
        "short"|"medium" => {
            for h in &hits {
                let (sl, sc) = byte_to_line_col(&h.content, h.m.start);
                // format: file:line:col: severity[rule]: message
                // e.g., g.js:2:3: warning[no-console]: Do not use console.log
                // col is 1-indexed? For g.js line "  console.log(1);" match at col 2 (0-indexed) -> displayed as 3 (1-indexed). Yes.
                println!("{}:{}:{}: {}[{}]: {}", h.file, sl+1, sc+1, h.severity, h.rule_id, h.message);
            }
        },
        _ => { // rich
            for h in &hits {
                println!("{}[{}]: {}", h.severity, h.rule_id, h.message);
                let (sl, sc) = byte_to_line_col(&h.content, h.m.start);
                println!("  ┌─ {}:{}:{}", h.file, sl+1, sc+1);
                println!("  │");
                let (_, _, lines_text, _, _) = line_range_for_match(&h.content, h.m.start, h.m.end);
                // lines_text may be multiline? For single-line, show line number and content with underline
                // For rich, original shows:
                // 3 │ console.log(x);
                //   │ ^^^^^^^^^^^^^^
                // Need to compute underline length = match length on that line? For single-line, underline is match length (without leading spaces?).
                // For multiline, show each line?
                let (msl, _) = byte_to_line_col(&h.content, h.m.start);
                let lines: Vec<&str> = h.content.lines().collect();
                // Find lines covered by match
                let (esl, _) = byte_to_line_col(&h.content, h.m.end);
                // Actually use lines_text split?
                // Simpler: show the lines from msl to esl
                for idx in msl..=esl {
                    if idx < lines.len() {
                        println!("{} │ {}", idx+1, lines[idx]);
                        // underline: for first line, from sc to end? For last line, from 0 to ec? For single line, from sc to ec?
                        let (s_l, s_c) = byte_to_line_col(&h.content, h.m.start);
                        let (e_l, e_c) = byte_to_line_col(&h.content, h.m.end);
                        let line_len = lines[idx].chars().count();
                        let (u_start, u_len) = if s_l==e_l {
                            // single line
                            (s_c, e_c - s_c)
                        } else if idx==s_l {
                            (s_c, line_len - s_c)
                        } else if idx==e_l {
                            (0, e_c)
                        } else {
                            (0, line_len)
                        };
                        // underline should account for leading spaces? Original underline starts at match start, with spaces for leading? For "  console.log(1);" match at col 2, underline is "  ^^^^^^^^^^^^^^" (2 spaces + carets). Our print is "{} │ {}{}"? Actually original shows "  │   ^^^^^^^^^^^^^^" with 2 spaces before carets? Let's replicate: print "  │ " + " ".repeat(u_start) + "^".repeat(u_len)
                        let spaces = " ".repeat(u_start);
                        let carets = "^".repeat(u_len.max(1));
                        println!("  │ {}{}", spaces, carets);
                    }
                }
                println!();
            }
        }
    }
    0
}

