fn do_scan(m: &clap::ArgMatches) -> i32 {
    let rule_file = m.get_one::<String>("rule").cloned();
    let inline_rules = m.get_one::<String>("inline-rules").cloned();
    let format = m.get_one::<String>("format").cloned();
    let report_style = m.get_one::<String>("report-style").unwrap().clone();
    let include_metadata = m.get_flag("include-metadata");
    let filter = m.get_one::<String>("filter").cloned();
    let config = m.get_one::<String>("config").cloned().unwrap_or("sgconfig.yml".to_string());
    let globs: Vec<String> = m.get_many::<String>("globs").map(|v| v.cloned().collect()).unwrap_or_default();
    let follow = m.get_flag("follow");
    let stdin_flag = m.get_flag("stdin");
    let threads: usize = 0; // ignore
    let interactive = m.get_flag("interactive");
    let update_all = m.get_flag("update-all");
    let files_with_matches = m.get_flag("files-with-matches");
    let has_json = m.contains_id("json");
    let json_opt = m.get_one::<String>("json").cloned();
    let color = m.get_one::<String>("color").unwrap().clone();
    let inspect = m.get_one::<String>("inspect").unwrap().clone();
    let after: usize = m.get_one::<String>("after").unwrap().parse().unwrap_or(0);
    let before: usize = m.get_one::<String>("before").unwrap().parse().unwrap_or(0);
    let context: usize = m.get_one::<String>("context").unwrap().parse().unwrap_or(0);
    let max_results: Option<usize> = m.get_one::<String>("max-results").and_then(|s| s.parse().ok());
    let paths: Vec<String> = m.get_many::<String>("paths").map(|v| v.cloned().collect()).unwrap_or(vec![".".to_string()]);
    // severity overrides
    // error/warning/info/hint/off are Vec<String> with require_equals, may be empty (meaning all)
    let get_list = |name: &str| -> Option<Vec<String>> {
        if m.contains_id(name) {
            let vals: Vec<String> = m.get_many::<String>(name).map(|v| v.cloned().collect()).unwrap_or_default();
            Some(vals)
        } else { None }
    };
    let err_list = get_list("error");
    let warn_list = get_list("warning");
    let info_list = get_list("info");
    let hint_list = get_list("hint");
    let off_list = get_list("off");

    // Load rules
    let mut rules: Vec<YamlRule> = Vec::new();
    if let Some(rf) = rule_file {
        let content = match std::fs::read_to_string(&rf) {
            Ok(c) => c,
            Err(e) => {
                eprintln!("Error: Cannot read rule file {}", rf);
                return 2;
            }
        };
        match parse_yaml_rules(&content) {
            Ok(mut r) => {
                // Check for invalid regex without kind
                for rr in &r {
                    if let Some(obj) = rr.rule_obj.as_mapping() {
                        if obj.contains_key(&serde_yaml::Value::String("regex".to_string())) && !obj.contains_key(&serde_yaml::Value::String("kind".to_string())) {
                            eprintln!("Error: Cannot parse rule {}", rf);
                            eprintln!("Help: The file is not a valid ast-grep rule. Please refer to doc and fix the error.");
                            eprintln!("See also: https://ast-grep.github.io/guide/rule-config.html");
                            eprintln!("\n✖ Caused by");
                            eprintln!("╰▻ Rule must specify a set of AST kinds to match. Try adding `kind` rule.");
                            return 2;
                        }
                    }
                }
                rules.append(&mut r);
            },
            Err(e) => {
                eprintln!("Error: Cannot parse rule {}", rf);
                eprintln!("Help: The file is not a valid ast-grep rule. Please refer to doc and fix the error.");
                eprintln!("See also: https://ast-grep.github.io/guide/rule-config.html");
                eprintln!("\n✖ Caused by");
                eprintln!("╰▻ {}", e);
                return 2;
            }
        }
    } else if let Some(inline) = inline_rules {
        match parse_yaml_rules(&inline) {
            Ok(mut r) => rules.append(&mut r),
            Err(e) => {
                eprintln!("Error: Cannot parse inline rules: {}", e);
                return 2;
            }
        }
    } else {
        // Load project config
        let cfg_path = Path::new(&config);
        let cfg_exists = cfg_path.exists();
        // Also try default sgconfig.yml in current dir if config is default and not exists? Already config is default.
        if !cfg_exists {
            eprintln!("Error: No ast-grep project configuration is found.");
            eprintln!("Help: You need to create an ast-grep project for this command. Try `sg new` to create one.");
            eprintln!("See also: https://ast-grep.github.io/guide/scan-project.html");
            eprintln!("");
            return 0;
        }
        // Parse sgconfig.yml
        let cfg_text = std::fs::read_to_string(&config).unwrap_or_default();
        // sgconfig.yml has ruleDirs, etc.
        let cfg_val: serde_yaml::Value = serde_yaml::from_str(&cfg_text).unwrap_or(serde_yaml::Value::Null);
        let mut rule_dirs: Vec<String> = Vec::new();
        if let Some(mapping) = cfg_val.as_mapping() {
            if let Some(rd) = mapping.get(&serde_yaml::Value::String("ruleDirs".to_string())) {
                if let Some(arr) = rd.as_sequence() {
                    for v in arr {
                        if let Some(s) = v.as_str() { rule_dirs.push(s.to_string()); }
                    }
                }
            }
        }
        if rule_dirs.is_empty() { rule_dirs.push("rules".to_string()); }
        for rd in rule_dirs {
            let rd_path = Path::new(&rd);
            if !rd_path.exists() { continue; }
            // walk for *.yml, *.yaml
            let walker = ignore::WalkBuilder::new(rd_path).hidden(false).build();
            for entry in walker {
                if let Ok(e) = entry {
                    let p = e.path();
                    if p.is_file() {
                        if let Some(ext) = p.extension().and_then(|s| s.to_str()) {
                            if ext=="yml"||ext=="yaml" {
                                if let Ok(txt) = std::fs::read_to_string(p) {
                                    if let Ok(mut r) = parse_yaml_rules(&txt) {
                                        rules.append(&mut r);
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
        // Apply filter if given
        if let Some(f) = filter.clone() {
            if let Ok(re) = regex::Regex::new(&f) {
                rules.retain(|r| re.is_match(&r.id));
            }
        }
    }

    // Apply severity overrides and off
    for r in rules.iter_mut() {
        // off
        if let Some(ref off) = off_list {
            if off.is_empty() || off.contains(&r.id) {
                r.severity = "off".to_string();
            }
        }
        if let Some(ref e) = err_list {
            if e.is_empty() || e.contains(&r.id) { r.severity = "error".to_string(); }
        }
        if let Some(ref w) = warn_list {
            if w.is_empty() || w.contains(&r.id) { r.severity = "warning".to_string(); }
        }
        if let Some(ref ii) = info_list {
            if ii.is_empty() || ii.contains(&r.id) { r.severity = "info".to_string(); }
        }
        if let Some(ref h) = hint_list {
            if h.is_empty() || h.contains(&r.id) { r.severity = "hint".to_string(); }
        }
    }
    // Remove off rules (unless? scan skips off by default)
    rules.retain(|r| r.severity != "off");

    // stdin handling for scan
    if stdin_flag {
        let code = read_stdin();
        // For stdin, need to determine language? Rules have language, so try each rule's language?
        // Original scan --stdin with rule.yml (js) on console.log(1) matched. It must have used rule's language to parse stdin.
        // We'll for each rule, try to match stdin content.
        let mut all_vals = Vec::new();
        let mut any_found = false;
        for rule in &rules {
            let lang_info = if let Some(ref l) = rule.language {
                match parse_lang(l) {
                    Some(li) => li,
                    None => continue,
                }
            } else { continue; };
            let ms = find_rule_matches(rule, &code, &lang_info.display);
            if ms.is_empty() { continue; }
            any_found = true;
            // output per format
            if has_json {
                for mm in &ms {
                    let mut v = match_to_json(mm, &code, "STDIN", &lang_info.display, rule.fix.as_deref());
                    // add rule fields
                    if let serde_json::Value::Object(ref mut map) = v {
                        map.insert("ruleId".to_string(), serde_json::Value::String(rule.id.clone()));
                        map.insert("severity".to_string(), serde_json::Value::String(rule.severity.clone()));
                        map.insert("message".to_string(), serde_json::Value::String(rule.message.clone()));
                        map.insert("note".to_string(), serde_json::Value::Null);
                        // labels?
                        let (sl, sc) = byte_to_line_col(&code, mm.start);
                        let (el, ec) = byte_to_line_col(&code, mm.end);
                        map.insert("labels".to_string(), serde_json::json!([{"text": mm.text, "range": {"byteOffset": {"start": mm.start, "end": mm.end}, "start": {"line": sl, "column": sc}, "end": {"line": el, "column": ec}}, "style": "primary"}]));
                        if include_metadata {
                            // include metadata? For now, empty?
                        }
                    }
                    all_vals.push(v);
                }
            } else if files_with_matches {
                println!("STDIN");
                break;
            } else {
                // rich/medium/short/github/sarif? For stdin, similar to file but with STDIN
                if let Some(ref fmt) = format {
                    if fmt=="github" {
                        for mm in &ms {
                            let (sl, _) = byte_to_line_col(&code, mm.start);
                            let (el, _) = byte_to_line_col(&code, mm.end);
                            println!("::{} file=STDIN,line={},endLine={},title={}::{}", rule.severity, sl+1, el+1, rule.id, rule.message);
                        }
                    } else if fmt=="sarif" {
                        // handled after loop? For stdin single, produce sarif? Simplify: ignore, print rich?
                    }
                } else {
                    match report_style.as_str() {
                        "short"|"medium" => {
                            for mm in &ms {
                                let (sl, sc) = byte_to_line_col(&code, mm.start);
                                println!("STDIN:{}:{}: {}[{}]: {}", sl+1, sc+1, rule.severity, rule.id, rule.message);
                            }
                        },
                        _ => {
                            for mm in &ms {
                                let (sl, sc) = byte_to_line_col(&code, mm.start);
                                println!("{}[{}]: {}", rule.severity, rule.id, rule.message);
                                println!("  ┌─ STDIN:{}:{}", sl+1, sc+1);
                                println!("  │");
                                // show lines?
                                let (_, _, lines_text, _, _) = line_range_for_match(&code, mm.start, mm.end);
                                for (idx, l) in lines_text.lines().enumerate() {
                                    println!("{} │ {}", sl+1+idx, l);
                                    println!("  │ {}", "^".repeat(l.trim_start().len().min(14)));
                                }
                                println!();
                            }
                        }
                    }
                }
            }
        }
        if has_json {
            let style = json_opt.clone().unwrap_or("pretty".to_string());
            if all_vals.is_empty() {
                match style.as_str() {
                    "stream" => {},
                    _ => println!("[]"),
                }
                return 0;
            }
            match style.as_str() {
                "stream" => { for v in all_vals { println!("{}", serde_json::to_string(&v).unwrap()); } },
                "compact" => println!("{}", serde_json::to_string(&serde_json::Value::Array(all_vals)).unwrap()),
                _ => println!("{}", serde_json::to_string_pretty(&serde_json::Value::Array(all_vals)).unwrap()),
            }
            return 0;
        }
        return 0;
    }

    // File mode
    // Check paths existence
    let mut errors: Vec<String> = Vec::new();
    let mut valid_paths: Vec<String> = Vec::new();
    for p in &paths {
        if !Path::new(p).exists() {
            errors.push(format!("ERROR: {}: No such file or directory (os error 2)", p));
        } else {
            valid_paths.push(p.clone());
        }
    }
    for e in &errors { eprintln!("{}", e); }

    // For each rule, collect files with its language
    // To avoid re-walking per rule, collect all files with any language? Simpler: for each rule, collect files filtered by its lang
    struct ScanHit {
        file: String,
        content: String,
        lang: LangInfo,
        rule_id: String,
        severity: String,
        message: String,
        note: Option<String>,
        m: MatchInfo,
        fix: Option<String>,
    }
    let mut hits: Vec<ScanHit> = Vec::new();
    for rule in &rules {
        let lang_info = if let Some(ref l) = rule.language {
            match parse_lang(l) {
                Some(li) => li,
                None => continue,
            }
        } else { continue; };
        // collect files for this lang
        let files = collect_files(&valid_paths, Some(&lang_info), &globs, follow);
        // Also need to handle rule's files/ignores globs? Ignore for now.
        for fp in files {
            let content_opt = std::fs::read(&fp).ok().and_then(|b| {
                if b.contains(&0) { return None; }
                String::from_utf8(b).ok()
            });
            let content = match content_opt { Some(c)=>c, None=>continue };
            let ms = find_rule_matches(rule, &content, &lang_info.display);
            for mm in ms {
                hits.push(ScanHit { file: fp.to_string_lossy().to_string(), content: content.clone(), lang: lang_info.clone(), rule_id: rule.id.clone(), severity: rule.severity.clone(), message: rule.message.clone(), note: rule.note.clone(), m: mm, fix: rule.fix.clone() });
                if let Some(max) = max_results {
                    if hits.len() >= max { break; }
                }
            }
            if let Some(max) = max_results {
                if hits.len() >= max { break; }
            }
        }
        if let Some(max) = max_results {
            if hits.len() >= max { break; }
        }
    }
    // Sort hits by file and start?
    hits.sort_by(|a,b| a.file.cmp(&b.file).then(a.m.start.cmp(&b.m.start)));

    if inspect != "nothing" {
        if inspect=="summary" {
            eprintln!("sg: summary|project: isProject=true");
            eprintln!("sg: summary|file: scannedFileCount={},skippedFileCount=0", valid_paths.len());
        }
    }

    if files_with_matches {
        let mut seen = std::collections::BTreeSet::new();
        for h in &hits { seen.insert(h.file.clone()); }
        for f in seen { println!("{}", f); }
        return 0;
    }
    if has_json {
        let style = json_opt.clone().unwrap_or("pretty".to_string());
        let mut vals = Vec::new();
        for h in &hits {
            let mut v = match_to_json(&h.m, &h.content, &h.file, &h.lang.display, h.fix.as_deref());
            if let serde_json::Value::Object(ref mut map) = v {
                map.insert("ruleId".to_string(), serde_json::Value::String(h.rule_id.clone()));
                map.insert("severity".to_string(), serde_json::Value::String(h.severity.clone()));
                // note
                if let Some(n) = &h.note {
                    map.insert("note".to_string(), serde_json::Value::String(n.clone()));
                } else {
                    map.insert("note".to_string(), serde_json::Value::Null);
                }
                map.insert("message".to_string(), serde_json::Value::String(h.message.clone()));
                let (sl, sc) = byte_to_line_col(&h.content, h.m.start);
                let (el, ec) = byte_to_line_col(&h.content, h.m.end);
                map.insert("labels".to_string(), serde_json::json!([{"text": h.m.text, "range": {"byteOffset": {"start": h.m.start, "end": h.m.end}, "start": {"line": sl, "column": sc}, "end": {"line": el, "column": ec}}, "style": "primary"}]));
            }
            vals.push(v);
        }
        if vals.is_empty() {
            match style.as_str() {
                "stream" => {},
                _ => println!("[]"),
            }
            return 0;
        }
        match style.as_str() {
            "stream" => { for v in vals { println!("{}", serde_json::to_string(&v).unwrap()); } },
