                // original: ::warning file=g.js,line=2,endLine=2,title=no-console::Do not use console.log
                // line numbers 1-indexed, endLine?
                println!("::{} file={},line={},endLine={},title={}::{}", h.severity, h.file, sl+1, el+1, h.rule_id, h.message);
            }
            return 0;
        } else if fmt=="sarif" {
            // Build SARIF json
            let mut results = Vec::new();
            for h in &hits {
                let (sl, sc) = byte_to_line_col(&h.content, h.m.start);
                let (el, ec) = byte_to_line_col(&h.content, h.m.end);
                let byte_len = h.m.end - h.m.start;
                results.push(serde_json::json!({
                    "level": h.severity,
                    "locations": [{
                        "physicalLocation": {
                            "artifactLocation": {"uri": h.file},
                            "region": {
                                "byteLength": byte_len,
                                "byteOffset": h.m.start,
                                "endColumn": ec+1,
                                "endLine": el+1,
                                "snippet": {"text": h.m.text},
                                "startColumn": sc+1,
                                "startLine": sl+1
                            }
                        }
                    }],
                    "message": {"text": h.message},
                    "ruleId": h.rule_id
                }));
            }
            let sarif = serde_json::json!({"runs": [{"results": results}]});
            println!("{}", serde_json::to_string_pretty(&sarif).unwrap());
            return 0;
        }
    }
    // Handle update-all for scan (apply fixes)
    if update_all {
        // Group by file
        let mut by_file: HashMap<String, (String, Vec<(MatchInfo, String)>)> = HashMap::new();
        for h in &hits {
            if let Some(fix) = &h.fix {
                let rep = apply_rewrite(fix, &h.m);
                by_file.entry(h.file.clone()).or_insert((h.content.clone(), Vec::new())).1.push((h.m.clone(), rep));
            }
        }
        let mut total = 0;
        for (f, (content, reps)) in by_file {
            let mut new_code = content.clone();
            let mut sorted = reps.clone();
            sorted.sort_by(|a,b| b.0.start.cmp(&a.0.start));
            for (mm, rep) in sorted {
                new_code.replace_range(mm.start..mm.end, &rep);
                total+=1;
            }
            std::fs::write(&f, new_code).ok();
        }
        if total>0 {
            println!("Applied {} changes", total);
        }
        // After update, still print diagnostics? Original scan -U prints diagnostics and applies? Let's check: scan with fix and -U? Not tested. For run -U, it prints "Applied X changes" and modifies files, no diff. For scan -U, likely similar. We'll just print applied and return.
        // Also need to print diagnostics? Original scan without -U prints diagnostics; with -U, does it still print? Probably prints diagnostics plus applies? Let's just print diagnostics as well? Simpler: if update_all, apply and also print diagnostics? For run, update_all does NOT print diff, just "Applied". For scan, similar? We'll just apply and return without printing diagnostics (to avoid double).
        // But to be safe, also print diagnostics? Let's check behavior: run -U with rewrite prints "Applied" and no diff. So scan -U should be similar (no diagnostics). We'll do that.
        return 0;
    }
    // Interactive? Stub: if interactive, print diagnostics and exit? Original interactive would start TUI, but in non-tty, what? Probably just print? We'll treat as normal (non-interactive) for now.

    // Default report styles
    match report_style.as_str() {
        "short"|"medium" => {
            for h in &hits {
                let (sl, sc) = byte_to_line_col(&h.content, h.m.start);
                // format: file:line:col: severity[rule]: message
                // e.g., g.js:2:3: warning[no-console]: Do not use console.log
                // col is 1-indexed? For g.js line "  console.log(1);" match at col 2 (0-indexed) -> displayed as 3 (1-indexed). Yes.
                println!("{}:{}:{}: {}[{}]: {}", h.file, sl+1, sc+1, h.severity, h.rule_id, h.message);
            }
        },
        _ => { // rich
            for h in &hits {
